// ─────────────────────────────────────────────────────────────────────────
// Path background PATTERNS — one composition per module, cloned.
//
// Source art: the hand-drawn symbol groups (Group 1/2/4/5/6/7.svg). Each
// artboard is a finished COMPOSITION and is kept exactly as drawn — same
// symbols, same arrangement, nothing added, nothing removed. The pattern is
// that composition stamped across the screen.
//
// What is computed here is only how the stamps sit next to each other:
//   • scale  — chosen so the average symbol INSIDE the composition reads at
//     a set optical mass, sqrt(w*h), on a 390pt-wide screen. Going by mass
//     rather than by bounding box is what keeps a 4.7:1 comet and a round
//     flower feeling equally heavy from module to module.
//   • pitchX / pitchY — the distance between clones: the composition's own
//     content box plus a gutter, so neighbours breathe instead of colliding.
//   • drop — every other column slides down half a row (a half-drop), which
//     is what stops a grid of identical stamps from reading as a spreadsheet.
//   • phaseX / phaseY — the whole field is nudged off the corner, so the
//     first clone is cropped mid-composition instead of sitting flush.
//
// GENERATED — edit scripts/genPathPatterns.js and re-run, not this file.
// ─────────────────────────────────────────────────────────────────────────

export interface PathPattern {
  /** module this pattern belongs to (1-based) */
  module: number;
  /** what the composition is, for whoever opens this file next */
  note: string;
  /** artboard it came from */
  source: string;
  /** the composition's paths, verbatim from the artboard */
  paths: string[];
  /** content box of the whole composition, in path units */
  bx: number;
  by: number;
  bw: number;
  bh: number;
  /** path units → pt */
  scale: number;
  /** distance between clones, pt */
  pitchX: number;
  pitchY: number;
  /** vertical offset of every other column, pt */
  drop: number;
  /** offset of the whole field, pt */
  phaseX: number;
  phaseY: number;
}

