/**
 * The pattern for a module, or null when that module has no art yet.
 * Only modules 1-6 are drawn so far; everything above falls back to the
 * plain solid Path background.
 */
export function getPathPattern(moduleNum: number): PathPattern | null {
  return PATH_PATTERNS.find((p) => p.module === moduleNum) ?? null;
}
